class ProjectRepo:
    def __init__(self, rows):
        self._rows = rows

    def get_for_actor(self, actor, project_id):
        if not actor or not actor.org_id:
            raise ValueError("missing actor org_id")
        row = self._rows.get(project_id)
        if row is None or row["org_id"] != actor.org_id:
            return None
        return row
